WITH totaux AS (
  SELECT v.client_id, SUM(v.quantite * p.prix) AS total
  FROM ventes AS v JOIN produits AS p ON p.id = v.produit_id
  WHERE v.client_id IS NOT NULL
  GROUP BY v.client_id
),
classes AS (
  SELECT client_id, total, RANK() OVER (ORDER BY total DESC) AS place FROM totaux
)
SELECT client_id, total, place FROM classes WHERE place <= 3 ORDER BY place, client_id;

